//! New whole-session measurements from the unmodified original 3.20 executable.
//! Fixtures are generated by tests/run_edge_runtime_diff.py under DOSBox AUTO.
use diada_core::{AnalysisConfig, AnalysisMode, InputSeries, Name, Real48};
use diada_io::*;

fn assert_runtime_report(
    input: &[u8],
    expected: &[u8],
    positions: usize,
    values: &[(&str, &str, &str, &str, &str)],
    forces: bool,
    selection: ReportSelection,
) {
    let document = EditableDialogue::open(input, "SCENE", &TpNumbers).unwrap();
    // The original loaded-and-saved journal must remain byte exact even for
    // the translational input journal and for more than one leading link.
    assert_eq!(document.current_journal().to_bytes(), input);
    let model = &document.loaded().mechanism;
    let number = |text: &str| TpNumbers.parse_real(text.as_bytes()).unwrap();
    let config = AnalysisConfig {
        positions,
        inputs: values
            .iter()
            .map(|(name, start, step, rate, eps)| InputSeries {
                link: model
                    .link_by_name(Name(LegacyName::from_text(name).unwrap().0))
                    .unwrap(),
                start: number(start),
                other_start: Real48::ZERO,
                rate: number(rate),
                rate_derivative: number(eps),
                step: number(step),
            })
            .collect(),
        mode: if forces {
            AnalysisMode::Kinetostatics
        } else {
            AnalysisMode::Kinematics
        },
    };
    let frames = model.sample_kinematics(&config).unwrap();
    assert_eq!(frames.len(), positions);
    let header = ReportHeader {
        mechanism_name: "SCENE".into(),
        source: InputSource::File,
        clock: ReportClock {
            year: 1999,
            month: 3,
            day: 10,
            hour: 10,
            minute: 38,
            second: 0,
        },
    };
    let actual = write_dif(
        &header,
        &position_reports(&frames, forces).unwrap(),
        &selection,
        &TpNumbers,
    )
    .unwrap();
    let first = actual
        .iter()
        .zip(expected)
        .position(|(a, b)| a != b)
        .unwrap_or(actual.len().min(expected.len()));
    assert_eq!(
        actual, expected,
        "whole original runtime report differs at byte {first}"
    );
}

macro_rules! measured {
    ($test:ident, $folder:literal, $positions:literal, $inputs:expr) => {
        #[test]
        fn $test() {
            assert_runtime_report(
                include_bytes!(concat!(
                    "../../../../tests/fixtures/diada-v320-edge-runtime/",
                    $folder,
                    "/SCENE.DI"
                )),
                include_bytes!(concat!(
                    "../../../../tests/fixtures/diada-v320-edge-runtime/",
                    $folder,
                    "/SCENE.DIF"
                )),
                $positions,
                $inputs,
                false,
                ReportSelection::default(),
            );
        }
    };
}

