#[test]
fn original_blank_filter_answers_revert_to_all_report_objects() {
    // Unlike a named list that matches no mobile objects, both blank input
    // lines produce nil original list heads: those heads mean all objects.
    assert_runtime_report(
        include_bytes!(
            "../../../../tests/fixtures/diada-v320-edge-runtime/rrp-empty-object-filter/SCENE.DI"
        ),
        include_bytes!(
            "../../../../tests/fixtures/diada-v320-edge-runtime/rrp-empty-object-filter/SCENE.DIF"
        ),
        7,
        &[("1", "137.5", "-17.5", "-2.25", "1.125")],
        false,
        ReportSelection::default(),
    );
}

#[test]
fn original_ground_only_filter_keeps_the_first_input_but_no_mobile_points() {
    assert_runtime_report(
        include_bytes!(
            "../../../../tests/fixtures/diada-v320-edge-runtime/rrp-ground-object-filter/SCENE.DI"
        ),
        include_bytes!(
            "../../../../tests/fixtures/diada-v320-edge-runtime/rrp-ground-object-filter/SCENE.DIF"
        ),
        5,
        &[("1", "15.75", "30.5", "1.5", "-0.125")],
        false,
        ReportSelection {
            links: Some(vec![LegacyName(*b"0 ")]),
            points: Some(vec![LegacyName(*b"O ")]),
            reactions: None,
        },
    );
}

#[test]
fn zero_external_force_skips_its_angle_and_matches_all_original_force_report_rows() {
    let input = include_bytes!(
        "../../../../tests/fixtures/diada-v320-edge-runtime/force-zero-external-seven/SCENE.DI"
    );
    let document = EditableDialogue::open(input, "SCENE", &TpNumbers).unwrap();
    let force = document
        .bindings()
        .iter()
        .find_map(|binding| match binding.path {
            FieldPath::ForceMagnitude(point) => Some(point),
            _ => None,
        })
        .unwrap();
    assert!(
        !document
            .bindings()
            .iter()
            .any(|binding| binding.path == FieldPath::ForceAngle(force))
    );
    let pair = document.loaded().mechanism.points[force.0].pair;
    assert_eq!(
        document.loaded().mechanism.pairs[pair.0].state.rx,
        Real48::ZERO
    );
    assert_eq!(
        document.loaded().mechanism.pairs[pair.0].state.ry,
        Real48::ZERO
    );
    assert_runtime_report(
        input,
        include_bytes!(
            "../../../../tests/fixtures/diada-v320-edge-runtime/force-zero-external-seven/SCENE.DIF"
        ),
        7,
        &[("1", "37.25", "0", "0", "0")],
        true,
        ReportSelection::default(),
    );
}

#[test]
fn zero_external_moments_and_reverse_grid_match_three_original_force_report_blocks() {
    assert_runtime_report(
        include_bytes!(
            "../../../../tests/fixtures/diada-v320-edge-runtime/force-zero-moments-thirteen/SCENE.DI"
        ),
        include_bytes!(
            "../../../../tests/fixtures/diada-v320-edge-runtime/force-zero-moments-thirteen/SCENE.DIF"
        ),
        13,
        &[("1", "98.125", "-37.25", "-1.375", "0.5625")],
        true,
        ReportSelection::default(),
    );
}
